-- Import dữ liệu nước thật T5/2026
-- Nguồn: file Excel "Nước Tháng 5THU năm 2026 (Autosaved).xlsx"
-- Sinh tự động bởi ChatGPT.
--
-- Chính sách an toàn:
-- 1) Tạo/cập nhật danh mục tuyến, nhóm giá, hộ dân cho toàn bộ 1430 dòng.
-- 2) Chỉ tạo/cập nhật meter_reading + invoice cho dòng hợp lệ: validation_flags = '' (1417 dòng).
-- 3) invoice: Thành tiền = source_amount (file gốc, đã gồm VAT). Sau import chạy: npm run db:apply-vat-inclusive (tách Giá + GTGT 5%, không đổi thành tiền).
-- 4) Sau import chạy: npm run db:mark-period-paid -- --year 2026 --month 5  (đánh dấu PAID, giữ nguyên số tiền).
--
-- Rà soát số liệu lần 2:
-- - Bổ sung 1 hộ bị bỏ sót trong pack trước: CAM KHE dòng Excel 128 - ĐẶNG VĂN ÁNH.
-- - Dòng này chưa có CSM/CSC/NTT/TT nên chỉ cập nhật household, không tạo reading/invoice.
-- Khuyến nghị: chạy trên database staging trước, kiểm tra số dòng, rồi mới chạy production.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- Nhóm giá mặc định theo file gốc: 9.500 đ/m3, đang coi là giá thành tiền đã thu/đã ghi trong file.
INSERT INTO price_group (id, code, name, unit_price)
VALUES (gen_random_uuid(), 'GIA_9500_FILE_GOC', 'Giá 9.500 đ/m³ theo file gốc T5/2026', 9500)
ON CONFLICT (code) DO UPDATE
SET name = EXCLUDED.name,
    unit_price = EXCLUDED.unit_price;

-- Kỳ thu T5/2026
INSERT INTO billing_period (id, year, month, status, created_at)
VALUES (gen_random_uuid(), 2026, 5, 'OPEN', now())
ON CONFLICT (year, month) DO UPDATE
SET status = EXCLUDED.status;

-- Tuyến thu
INSERT INTO collection_route (id, code, name, sort_order, unit_price)
VALUES
(gen_random_uuid(), 'D212', 'DUONG 212', 1, NULL),
(gen_random_uuid(), 'BV', 'BANG VIEN', 2, NULL),
(gen_random_uuid(), 'DHANH', 'DOC HANH', 3, NULL),
(gen_random_uuid(), 'X10', 'XOM 10', 4, NULL),
(gen_random_uuid(), 'DQ', 'DONG QUY', 5, NULL),
(gen_random_uuid(), 'CK', 'CAM KHE', 6, NULL),
(gen_random_uuid(), 'MT', 'MINH THI', 7, NULL),
(gen_random_uuid(), 'DHAU', 'DOC HAU', 8, NULL)
ON CONFLICT (code) DO UPDATE
SET name = EXCLUDED.name,
    sort_order = EXCLUDED.sort_order,
    unit_price = EXCLUDED.unit_price;

CREATE TEMP TABLE stg_water_import_t5_2026 (
    source_sheet text,
    source_row int,
    route_code text,
    route_name text,
    route_sort_order int,
    household_code text,
    meter_code text,
    resident_name text,
    phone text,
    source_serial text,
    invoice_no text,
    csc double precision,
    csm double precision,
    usage_m3 double precision,
    source_amount double precision,
    note text,
    validation_flags text
) ON COMMIT DROP;

