-- Cập nhật danh mục hộ.
INSERT INTO household (
    id, household_code, meter_code, address, resident_name, contact_phone,
    status, payment_method, note, collection_route_id, route_sort_order, price_group_id,
    created_at, updated_at
)
SELECT
    gen_random_uuid(),
    s.household_code,
    s.meter_code,
    s.route_name AS address,
    s.resident_name,
    s.phone,
    'ACTIVE',
    'CASH',
    NULLIF(concat_ws('; ',
        s.note,
        'Nguồn Excel: ' || s.source_sheet || ' dòng ' || s.source_row,
        CASE WHEN s.source_serial IS NOT NULL THEN 'Số sơ ri gốc: ' || s.source_serial ELSE NULL END,
        CASE WHEN s.validation_flags <> '' THEN 'Cảnh báo: ' || s.validation_flags ELSE NULL END
    ), ''),
    cr.id,
    s.route_sort_order,
    p.id,
    now(),
    now()
FROM stg_water_import_t5_2026 s
JOIN collection_route cr ON cr.code = s.route_code
JOIN price_group p ON p.code = 'GIA_9500_FILE_GOC'
ON CONFLICT (household_code) DO UPDATE
SET meter_code = EXCLUDED.meter_code,
    address = EXCLUDED.address,
    resident_name = EXCLUDED.resident_name,
    contact_phone = EXCLUDED.contact_phone,
    status = EXCLUDED.status,
    payment_method = EXCLUDED.payment_method,
    note = EXCLUDED.note,
    collection_route_id = EXCLUDED.collection_route_id,
    route_sort_order = EXCLUDED.route_sort_order,
    price_group_id = EXCLUDED.price_group_id,
    updated_at = now();

-- Chỉ số đồng hồ: chỉ nạp các dòng không có cảnh báo.
INSERT INTO meter_reading (
    id, household_id, period_id, old_reading, ocr_value, confirmed_value,
    usage_m3, status, input_method, image_path, anomaly_flags,
    submitted_at, confirmed_at
)
SELECT
    gen_random_uuid(),
    h.id,
    bp.id,
    s.csc,
    NULL,
    s.csm,
    s.usage_m3,
    'CONFIRMED',
    'MANUAL',
    NULL,
    '[]',
    now(),
    now()
FROM stg_water_import_t5_2026 s
JOIN household h ON h.household_code = s.household_code
JOIN billing_period bp ON bp.year = 2026 AND bp.month = 5
WHERE COALESCE(s.validation_flags, '') = ''
ON CONFLICT (household_id, period_id) DO UPDATE
SET old_reading = EXCLUDED.old_reading,
    confirmed_value = EXCLUDED.confirmed_value,
    usage_m3 = EXCLUDED.usage_m3,
    status = EXCLUDED.status,
    input_method = EXCLUDED.input_method,
    anomaly_flags = EXCLUDED.anomaly_flags,
    submitted_at = EXCLUDED.submitted_at,
    confirmed_at = EXCLUDED.confirmed_at;

-- Hóa đơn: Thành tiền = source_amount (đã gồm VAT); tạm vat=0 — chạy db:apply-vat-inclusive để tách 5%.
INSERT INTO invoice (
    id, household_id, period_id, usage_m3, unit_price,
    subtotal_amount, vat_percent, vat_amount, total_amount,
    pdf_path, status, issued_at, zalo_sent_at, zalo_message_id,
    created_at, updated_at
)
SELECT
    gen_random_uuid(),
    h.id,
    bp.id,
    s.usage_m3,
    CASE WHEN s.usage_m3 > 0 THEN ROUND((s.source_amount / s.usage_m3)::numeric, 2)::double precision ELSE 9500 END AS unit_price,
    s.source_amount,
    0,
    0,
    s.source_amount,
    NULL,
    'ISSUED',
    now(),
    NULL,
    NULL,
    now(),
    now()
FROM stg_water_import_t5_2026 s
JOIN household h ON h.household_code = s.household_code
JOIN billing_period bp ON bp.year = 2026 AND bp.month = 5
WHERE COALESCE(s.validation_flags, '') = ''
ON CONFLICT (household_id, period_id) DO UPDATE
SET usage_m3 = EXCLUDED.usage_m3,
    unit_price = EXCLUDED.unit_price,
    subtotal_amount = EXCLUDED.subtotal_amount,
    vat_percent = EXCLUDED.vat_percent,
    vat_amount = EXCLUDED.vat_amount,
    total_amount = EXCLUDED.total_amount,
    status = EXCLUDED.status,
    issued_at = EXCLUDED.issued_at,
    updated_at = now();

-- Kiểm tra nhanh sau import.
SELECT 'staging_rows' AS metric, COUNT(*)::text AS value FROM stg_water_import_t5_2026
UNION ALL
SELECT 'flagged_rows', COUNT(*)::text FROM stg_water_import_t5_2026 WHERE COALESCE(validation_flags,'') <> ''
UNION ALL
SELECT 'valid_reading_invoice_rows', COUNT(*)::text FROM stg_water_import_t5_2026 WHERE COALESCE(validation_flags,'') = ''
UNION ALL
SELECT 'valid_usage_m3', COALESCE(SUM(usage_m3),0)::text FROM stg_water_import_t5_2026 WHERE COALESCE(validation_flags,'') = ''
UNION ALL
SELECT 'valid_total_amount', COALESCE(SUM(source_amount),0)::text FROM stg_water_import_t5_2026 WHERE COALESCE(validation_flags,'') = '';

COMMIT;
